import { mulberry32, shuffled } from './rng';

export type Region = { id: string; x: number; y: number; width: number; height: number; color: string };
type Rect = Omit<Region, 'id' | 'color'>;
const NEUTRAL = '#f4f0df';
const ACCENTS = ['#d7261e', '#1357a6', '#f3c623'] as const;

export function createSubdivision(seed: number): Region[] {
  const random = mulberry32(seed);
  const leaves: Rect[] = [];
  function split(rect: Rect, depth: number): void {
    const shouldStop = depth >= 5 || (depth >= 2 && random() < 0.28) || Math.min(rect.width, rect.height) < 12;
    if (shouldStop) { leaves.push(rect); return; }
    const vertical = rect.width > rect.height * 1.18 ? true : rect.height > rect.width * 1.18 ? false : random() > 0.5;
    const ratio = 0.34 + random() * 0.32;
    if (vertical) {
      const firstWidth = rect.width * ratio;
      split({ ...rect, width: firstWidth }, depth + 1);
      split({ x: rect.x + firstWidth, y: rect.y, width: rect.width - firstWidth, height: rect.height }, depth + 1);
    } else {
      const firstHeight = rect.height * ratio;
      split({ ...rect, height: firstHeight }, depth + 1);
      split({ x: rect.x, y: rect.y + firstHeight, width: rect.width, height: rect.height - firstHeight }, depth + 1);
    }
  }
  split({ x: 0, y: 0, width: 100, height: 100 }, 0);
  const regions: Region[] = leaves.map((rect, index) => ({ ...rect, id: `leaf-${index}`, color: NEUTRAL }));
  const candidates = shuffled(regions.map((region, index) => ({ index, area: region.width * region.height })), random)
    .filter(({ area }) => area > 250)
    .slice(0, ACCENTS.length);
  candidates.forEach(({ index }, accentIndex) => { regions[index].color = ACCENTS[accentIndex]; });
  return regions;
}

